rowdata.pyStepsJavaSource:
try {
    String dependentAssignment = tools.getDatabase().getHandle(myStepPage);
	String errMessage = "Hit: " + dependentAssignment + " is in pyTopCaseMap";
	pega_rules_default.LogAgentMessage(tools, "Pega-ProcessEngine", "pzProcessIndividualDepAssignment", tools.getPrimaryPage().getClassName(), errMessage);
} catch (DatabaseException dbe) {
  oLog.error(dbe);
}

ClipboardPage activatorWorkPage = tools.findPage(tools.getParamValue("pyActivatorPageName"));

String depStatus = activatorWorkPage.getString("pyDesiredStatus");
String cleanActivatorClassName = pega_processengine_workutilities.pxPageNameClean(activatorWorkPage.getString("pxObjClass"));
ClipboardPage activatorList = myStepPage.getProperty("pxPages").getPageValue(cleanActivatorClassName);
ClipboardProperty activatorListResults = activatorList.getProperty("pxResults");
ClipboardPage curDepPage = tools.getPrimaryPage();
String completeDependentWhen = curDepPage.getString("pyCompleteDependentWhen");
String waitForAllCases = curDepPage.getString("pyWaitForAllCases");

StringMap wKeys = null;
ParameterPage wParams = null;
canComplete = false;

if (!completeDependentWhen.equals("")) {
	wKeys = new HashStringMap();
	wKeys.putString("pyActivityName", "pzActivatorFulfillsWhenRule");
	wKeys.putString("pyClassName", activatorWorkPage.getClassName());
	wParams = new ParameterPage();
	wParams.putString("BlockName", completeDependentWhen);

}
if ( !completeDependentWhen.equals("")) { 
	if(!waitForAllCases.equals("true")) {
		if (activatorWorkPage != null) {	
				tools.doActivity(wKeys, activatorWorkPage, wParams);
				if (wParams.getAsBoolean("WhenResult")) {
					canComplete = true;
					return true;
				}
			}
		}
}

if(waitForAllCases.equals("true")){
	// Get dependent's ancestor class name if valid class name
	boolean bUseAncestor = false;
	String dependentAncestorKey = "";
	String ancestorClassName = curDepPage.getString("pyDependencyAncestorClass");
  String ancestorKey = curDepPage.getString("pyDependencyAncestorKey");
	if (!ancestorClassName.equals("") && !ancestorClassName.equals("pzNoAncestorClass")) {
		ancestorClassName = pega_processengine_workutilities.pzPageNameClean(tools, ancestorClassName);
		dependentAncestorKey = pega_processengine_workutilities.pzGetCommonAncestor(tools, myStepPage, curDepPage.getString("pyWorkObjectInsKey"), pega_processengine_workutilities.pzPageNameClean(tools, curDepPage.getString("pyWorkObjectClassName")),ancestorClassName,ancestorKey);
		bUseAncestor = true;
	} else {
		ancestorClassName = "";
	}
	Iterator i = activatorListResults.iterator();
	ClipboardProperty curActivatorProp;
	ClipboardPage curActivator;
	ParameterPage activityParams = new ParameterPage();
	activityParams.putString("DependentStatus", activatorWorkPage.getString("pyDesiredStatus"));
	String[] classNameParts;


	StringMap aKeys = new HashStringMap();
	aKeys.putString("pxObjClass", "Rule-Obj-Activity");
	aKeys.putString("pyActivityName", "pzGetAllStatusforDepClass");
	String classGroup = "";
	boolean allTrueWhensReached = false;


	while (i.hasNext()) { // for each of the activator 
		curActivatorProp = (ClipboardProperty)i.next();
		curActivator = curActivatorProp.getPageValue();
	// First check if the activator satisfies the status

		if (bUseAncestor) {
			// If we need to consider the ancestor then see if the ancestor keys match. If not then this activator is not a factor.
			String activatorAncestorKey = pega_processengine_workutilities.pzGetCommonAncestor(tools, myStepPage, curActivator.getString("pzInsKey"), cleanActivatorClassName, ancestorClassName,ancestorKey);
			if (!activatorAncestorKey.equals(dependentAncestorKey)) {
				continue;
			}
      // If activator and dependent are same WO, it is not a valid factor
      if(curActivator.getString("pzInsKey").equals(curDepPage.getString("pyWorkObjectInsKey"))){
        continue;
      }
		}
		canComplete = false;
       //making sure to be resolved wait condition is satisifed
		if( pega_processengine_workutilities.pzEvaluateDependencyRelation(depStatus,curActivator.getString("pyStatusWork")) ){
		//if(curActivator.getString("pyStatusWork").equals(depStatus)){
			canComplete = true;
		}
		else {
			activityParams.remove("StatusFromHistoryFound");
			activityParams.putString("InsKey", curActivator.getString("pzInsKey"));

			if (classGroup.equals("")) {
				classGroup = pega_rules_default.getClassGroupName(activatorList.getString("pyClassName"));
				if (classGroup.equals("")) {
					canComplete = true;
				}
			}
			if (!classGroup.equals("")) {
				activityParams.putString("objClass", classGroup);

				tools.doActivity(aKeys, activatorWorkPage, activityParams);
				if (activityParams.getString("StatusFromHistoryFound").equals("true")) {
					canComplete = true;
				} else {

					if(completeDependentWhen.equals("")){ // Make sure there is no WHEN specified 
						break;
					}
				}
			}
		}


		// second check if the activator satisfies WHEN rule if present

		if (!completeDependentWhen.equals("")) { // If when rule specified

			String curpzInsKey = curActivator.getString(".pzInsKey");
			ClipboardPage curActivatorWorkPage = tools.findPageByHandle(curpzInsKey);

			if(curActivatorWorkPage == null) { // If not available on the clipboard, open from the database 

				try{	
					activatorWorkPage = tools.getDatabase().open(curActivator.getString("pzInsKey"), true, false, false, null);             
				}
				catch (DatabaseException de) {
					oLog.error(de.getMessage());
				}

			}
			else {
				activatorWorkPage = curActivatorWorkPage;

			}

			if (activatorWorkPage != null) {
				tools.doActivity(wKeys, activatorWorkPage, wParams);
				if (!wParams.getAsBoolean("WhenResult")) { // Ignore this instance; we are filtering out the ones that didn't pass WHEN rule; so do not break; continue 
					canComplete = false;
				}
				else {
					if(!canComplete){  // This is the case where an instance of activator has passed the WHEN rule but didn't reach the satisfying status; So we found atleast one instance for failing condition; so break
						allTrueWhensReached = false;
						break;
					}
					else {
						canComplete = true; // WHEN passed and status reached; so continue 
						allTrueWhensReached = true;

					}

				}
			}

		} // WHEN if 


	} // while loop

	if (!completeDependentWhen.equals("")){ // If WHEN specified, we are considering only the ones that did pass the WHEN rule 
		canComplete = allTrueWhensReached;

	}
}

String insKey = myStepPage.getString(".pyWorkObjectInsKey");
ClipboardPage coverPage = tools.findPage("pyWorkCover");
if (coverPage != null && pega_rules_page.getPageHandle(coverPage).equals(insKey)) {
	DependentWorkPage = "pyWorkCover";
	usingPreexistingPage = true;
} else {
	ClipboardPage curWorkPage = pega_rules_page.findPageByHandle(insKey);
	if(curWorkPage != null && curWorkPage.getProperty("pyStatusWork") != null && curWorkPage.getString("pyStatusWork")!=""){
	//if (curWorkPage != null) {
		DependentWorkPage = curWorkPage.getReference();
		if (DependentWorkPage.equals("pyTopCaseWork")) {
			DependentWorkPage = "";
		}
		else
			usingPreexistingPage = true;
	}
}

if (((LogHelper)lh).isDebugEnabled()) {
  ((LogHelper)lh).debug("pzProcessIndividualDepAssignment: Cannot lock, queueing activator change: " + tools.findPage("CurrentDepAssign").getString(".pyWorkObjectInsKey"));
}

// Log Agent Message
String errMessage = "pzProcessIndividualDepAssignment: Cannot lock, queueing activator change: " + tools.findPage("CurrentDepAssign").getString(".pyWorkObjectInsKey");
pega_rules_default.LogAgentMessage(tools, "Pega-ProcessEngine", "pzProcessIndividualDepAssignment", tools.getPrimaryPage().getClassName(), errMessage);

ClipboardPage currentDepAssign = tools.findPage("CurrentDepAssign");
if (currentDepAssign != null) 
{
    String strAssignHandle = currentDepAssign.getString(".pxInsIndexedKey");
    if (strAssignHandle.length() > 0)
    {
        // Open the assignment without security, since this is the process engine pushing it forward, not a user
        try {
            ClipboardPage assignmentPage = tools.getDatabase().open(strAssignHandle, false);
            if (assignmentPage != null) {
                myStepPage = pega.setStepPage("DependentAssignPage", assignmentPage);
            } else {
                tools.getStepStatus().set(ProcessingStatus.SEVERITY_FAIL,"Database-Instance-NotFound", strAssignHandle);
            }
        }
        catch (DatabaseException e)
        {
            throw new PRAppRuntimeException("Pega-ProcessEngine", 0, e.getMessage());
        }
    }
}

if (((LogHelper)lh).isDebugEnabled()) {
  ((LogHelper)lh).debug("pzProcessIndividualDepAssignment: Completing dependency " + myStepPage.getString("pzInsKey") + ", action " + curActionName);
}

String errMessage = "RunFlowActionActivity on " + tools.getParamValue("DependentAssignPage") + ".\n";
pega_rules_default.LogAgentMessage(tools, "Pega-ProcessEngine", "pzProcessIndividualDepAssignment", tools.getPrimaryPage().getClassName(), errMessage);

if (((LogHelper)lh).isDebugEnabled()) {
  ((LogHelper)lh).debug("pzProcessIndividualDepAssignment: Problem completing dependency: " + ProblemFlowErrorMessage);
}
String errMessage = "There was an error" + ProblemFlowErrorMessage + ".\n";
pega_rules_default.LogAgentMessage(tools, "Pega-ProcessEngine", "pzProcessIndividualDepAssignment", tools.getPrimaryPage().getClassName(), errMessage);
